-- SLOW: Materializes entire subquery result
SELECT * FROM orders o 
WHERE o.user_id IN (
  SELECT u.id FROM users u WHERE u.active = true
);

-- FAST: Short-circuits on first match
SELECT * FROM orders o
WHERE EXISTS (
  SELECT 1 FROM users u 
  WHERE u.id = o.user_id AND u.active = true
);

-- Regular: Still reads table heap
CREATE INDEX idx_users_active_date ON users(active, created_at);

-- Covering: Index-only scan magic
CREATE INDEX idx_users_covering ON users(active, created_at) 
INCLUDE (id, email, name);
